+import QtQuick
+
+import org.kde.plasma.core as PlasmaCore
+import org.kde.kirigami as Kirigami
+import org.kde.plasma.plasmoid
+
+import org.kde.plasma.private.volume
+
+PlasmoidItem {
+    id: root
+
+    readonly property bool inEmbeddedContainment: Plasmoid.containment.containmentType === PlasmaCore.Containment.CustomEmbedded
+
+    Plasmoid.icon: MicrophoneIndicator.iconName
+    Plasmoid.status: MicrophoneIndicator.active ? PlasmaCore.Types.ActiveStatus : inEmbeddedContainment ? PlasmaCore.Types.HiddenStatus : PlasmaCore.Types.PassiveStatus
+
+    toolTipMainText: MicrophoneIndicator.toolTipMainText
+    toolTipSubText: MicrophoneIndicator.toolTipSubText
+
+    preferredRepresentation: fullRepresentation
+    fullRepresentation: MouseArea {
+        acceptedButtons: Qt.LeftButton | Qt.MiddleButton
+        hoverEnabled: true
+
+        onClicked: MicrophoneIndicator.toggleMuted()
+        onWheel: wheel => MicrophoneIndicator.scroll(wheel.angleDelta.y)
+
+        Kirigami.Icon {
+            anchors.fill: parent
+            source: Plasmoid.icon
+            active: parent.containsMouse
+        }
+
+        PlasmaCore.ToolTipArea {
+            anchors.fill: parent
+            mainText: root.toolTipMainText
+            subText: root.toolTipSubText
+        }
+    }
+
+    Plasmoid.contextualActions: [
+        PlasmaCore.Action {
+            text: i18n("Mute")
+            icon.name: Qt.application.layoutDirection === Qt.RightToLeft ? "microphone-sensitivity-muted-rtl" : "microphone-sensitivity-muted"
+            checkable: true
+            checked: MicrophoneIndicator.muted
+            onTriggered: checked => MicrophoneIndicator.setMuted(checked)
+        }
+    ]
+}
